const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;
  const title = (json.title || '').toLowerCase();
  const description = (json.description || '').toLowerCase();
  const text = `${title} ${description}`;
  const ticketId = json.id || json.ticketId;

  // Category Classification
  let category = 'other';
  if (text.includes('factura') || text.includes('cobro') || text.includes('pago')) {
    category = 'billing';
  } else if (text.includes('bug') || text.includes('error') || text.includes('servidor')) {
    category = 'technical';
  } else if (text.includes('cuenta') || text.includes('login') || text.includes('password')) {
    category = 'account';
  }

  // Priority Classification
  let priority = 'medium';
  if (text.includes('caído') || text.includes('urgente') || text.includes('crítico')) {
    priority = 'urgent';
  } else {
    priority = 'low';
  }

  // Dynamic Tags Extraction
  const tags = [];
  const potentialTags = ['factura', 'cobro', 'pago', 'bug', 'error', 'servidor', 'cuenta', 'login', 'password', 'caído', 'urgente', 'crítico', 'android', 'ios', 'api', 'email', 'reembolso'];
  for (const tag of potentialTags) {
    if (text.includes(tag)) {
      tags.push(tag);
    }
  }

  // Suggested Reply Generation
  let suggestedReply = 'Hola, hemos recibido tu solicitud y nuestro equipo de soporte la está revisando. Nos pondremos en contacto contigo a la brevedad.';
  if (category === 'billing') {
    suggestedReply = 'Hola, lamentamos el inconveniente con tu cobro o factura. Estamos revisando los detalles de la transacción para resolverlo cuanto antes.';
  } else if (category === 'technical') {
    suggestedReply = 'Hola, gracias por reportar este error técnico. Nuestro equipo de ingeniería ya ha sido notificado para investigar el origen del problema.';
  } else if (category === 'account') {
    suggestedReply = 'Hola, entendemos que tienes problemas con tu cuenta o acceso. Por seguridad, te guiaremos paso a paso para restablecer tu sesión de forma segura.';
  }

  if (priority === 'urgent') {
    suggestedReply = '¡Atención URGENTE! Hemos priorizado tu caso debido a la criticidad reportada. Un especialista senior se encuentra atendiendo esta incidencia ahora mismo.';
  }

  results.push({
    json: {
      ticketId: Number(ticketId),
      priority,
      category,
      tags,
      suggestedReply
    }
  });
}

return results;
